package com.projectdark.mobile;
import android.content.Context;import android.graphics.*;import com.projectdark.mobile.world.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.nio.file.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class RucesionTownV154Test {
 Context c;
 @Before public void reset(){c=RuntimeEnvironment.getApplication();for(String key:new String[]{"project_dark_f5m_v1","project_dark_skill_book_v1","project_dark_skill_test_v1"})c.getSharedPreferences(key,0).edit().clear().commit();F5mSaveStore.install(c);}
 Object call(GameView v,String n,Class<?>[] types,Object...args)throws Exception{Method m=GameView.class.getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(v,args);}
 GameView town()throws Exception{GameView v=new GameView(c);v.layout(0,0,960,540);call(v,"enterPoteField",new Class<?>[]{});call(v,"changeCampaignMap",new Class<?>[]{String.class,boolean.class},RucesionTownGeometry.ID,false);return v;}
 void save(Bitmap b,String n)throws Exception{java.nio.file.Path p=Paths.get("build/reports/town-v154/"+n+".png");Files.createDirectories(p.getParent());try(OutputStream out=Files.newOutputStream(p)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,out));}}
 @Test public void expandedTownRendersActualNativeDistrictsAndRetainsBoundedWarmCache()throws Exception{
  GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");assertTrue(s.monsters().isEmpty());assertTrue(CampaignWorld.connectedTiles(RucesionTownGeometry.ID).size()>3500);assertEquals(RucesionTownGeometry.navigation().size(),CampaignWorld.connectedTiles(RucesionTownGeometry.ID).size());assertEquals(20,RucesionTownGeometry.PROPS.stream().filter(p->p.asset.startsWith("building_")).count());assertNull(CampaignWorld.next(RucesionTownGeometry.ID));WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");RucesionTownRenderer renderer=new RucesionTownRenderer(c);renderer.prepare();
  for(int[] uv:new int[][]{{38,39},{16,37},{27,24},{38,17},{14,25},{66,52},{83,60},{70,20}}){w.camera().snapTo(RucesionTownGeometry.x(uv[0],uv[1]),RucesionTownGeometry.y(uv[0],uv[1])-100);Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);renderer.draw(new Canvas(b),w,Collections.emptyList());save(b,"rucesion-"+uv[0]+"-"+uv[1]);assertTrue(renderer.floorCacheEntries()<=32);assertTrue(renderer.floorCachePixelBytes()<=8652800);long cold=renderer.floorBuildCount();for(int i=0;i<30;i++)renderer.draw(new Canvas(b),w,Collections.emptyList());assertEquals(cold,renderer.floorBuildCount());}
  w.resizeViewport(6656,3584);w.camera().snapTo(3328,1792);Bitmap full=Bitmap.createBitmap(1997,1076,Bitmap.Config.ARGB_8888);Canvas cc=new Canvas(full);cc.scale(.3f,.3f);renderer.draw(cc,w,Collections.emptyList());save(full,"rucesion-whole-native");
 }
 @Test public void allThreeServicesUseActualTouchEntryAndSaveRestoreExitToSameTown()throws Exception{
  for(RucesionTownGeometry.Building b:RucesionTownGeometry.BUILDINGS){reset();GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");s.player().x=RucesionTownGeometry.x(b.prop.u,b.prop.v+2);s.player().y=RucesionTownGeometry.y(b.prop.u,b.prop.v+2);assertTrue(w.canPlayerOccupy(s.player().x,s.player().y));w.cancelForAction();w.snapCameraToPlayer();WorldCameraTransform.Point at=w.worldToScreen(b.doorX(),b.doorY());Bitmap actual=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(actual));save(actual,b.id+"-portal");TownInteriorTest.tap(v,at.x,at.y);for(int i=0;i<180&&RucesionTownGeometry.ID.equals(s.currentMapId());i++)TownInteriorTest.tick(v,1);assertEquals(b.interior,s.currentMapId());assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView restored=new GameView(c);restored.layout(0,0,960,540);RuntimeState rs=TownInteriorTest.field(restored,"state");assertEquals(b.interior,rs.currentMapId());TownInteriorDef d=TownInteriorDef.forMap(b.interior);assertTrue(d.isRegional());call(restored,"leaveReagentShop",new Class<?>[]{});assertEquals(RucesionTownGeometry.ID,rs.currentMapId());assertNull(RucesionTownGeometry.doorAt(rs.player().x,rs.player().y));assertFalse(rs.blocked(rs.player().x,rs.player().y));}
 }
 @Test public void cleanObjectSpritesHaveTransparentGutters()throws Exception{
  for(String name:new String[]{"building_blue_hall","building_yellow_shop","building_blue_house","pergola_garden","tree_broadleaf","rowing_boat"}){Bitmap b=BitmapFactory.decodeStream(c.getAssets().open("rucesion-v154/"+name+".png"));assertNotNull(b);for(int x=0;x<b.getWidth();x++){assertEquals(0,Color.alpha(b.getPixel(x,0)));assertEquals(0,Color.alpha(b.getPixel(x,b.getHeight()-1)));}for(int y=0;y<b.getHeight();y++){assertEquals(0,Color.alpha(b.getPixel(0,y)));assertEquals(0,Color.alpha(b.getPixel(b.getWidth()-1,y)));}}
 }
 @Test public void sixActualNpcRoundTripsPreserveProgressAndRestoreTownSave()throws Exception{
  GameView v=town();RuntimeState s=TownInteriorTest.field(v,"state");long exp=CampaignProgress.earnedExp(s.rpg());
  for(int i=0;i<6;i++)for(String id:new String[]{"rucesion_town_travel","abel_town_travel"}){RuntimeState.Npc n=s.npcs().stream().filter(a->a.id.equals(id)).findFirst().get();WorldRuntimeAdapter w=TownInteriorTest.field(v,"poteFieldAdapter");assertTrue(CampaignNavigationTest.walk(w,w.requestNpcApproach(n.id)));assertEquals(InteractionController.TickResult.DIALOG_OPENED,((InteractionController)TownInteriorTest.field(v,"interaction")).request(s,n));TownInteriorTest.tap(v,TownTravelWindow.cardFor(s.currentMapId(),id.startsWith("rucesion")?AbelTownGeometry.ID:RucesionTownGeometry.ID).centerX(),TownTravelWindow.cardFor(s.currentMapId(),id.startsWith("rucesion")?AbelTownGeometry.ID:RucesionTownGeometry.ID).centerY());assertEquals(id.startsWith("rucesion")?AbelTownGeometry.ID:RucesionTownGeometry.ID,s.currentMapId());}
  assertEquals(exp,CampaignProgress.earnedExp(s.rpg()));assertTrue(F5mSaveStore.checkpointActive());F5mSaveStore.install(c);GameView fresh=new GameView(c);assertEquals(RucesionTownGeometry.ID,((RuntimeState)TownInteriorTest.field(fresh,"state")).currentMapId());Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));save(b,"actual-town-return");
 }
}
